SELECT msi.server_id, msi.server_name, msi.layer_name, msi.file_type, msi.server_status, msi.publish_time, msi.publishor, msi.update_time, msi.data_type, msi.file_url, msi.is_public, msi.description, msi.open_tiled, msi.pulished_proctol, mfi.feature_id, mfi.resource_crs, mfi.native_crs, mfi.projection_policy, mfi.native_bbox, mfi.resource_bbox, mfi.tile_width, mfi.tile_height, mfi.zoom_level, mfi.sea_chart_scale, mfi.tile_origin_flag, mfi.input_transparent_color, mfi.output_transparent_color FROM map_server_info msi left join map_feature_info mfi on msi.server_id = mfi.server_id where msi.data_type NOT IN (6,7) and (msi.pulished_proctol ~* 'wmts' or msi.pulished_proctol ~* 'tms') and msi.is_public = 1 and msi.server_show = 0
and msi.server_name ~* #{serverName}
order by msi.publish_time desc
LIMIT ${pageInfo.pageSize} offset (${pageInfo.pageNum} - 1)*${pageInfo.pageSize}

